const state=ref(demo?seed():null),userId=ref(demo?'u1':''),tenantId=ref('t1'),page=ref('dashboard'),search=ref(''),statusFilter=ref('All work orders'),drawer=ref(false),busy=ref(false),toast=ref(''),failure=ref(''),mobileMenu=ref(false),dialog=ref(''),selected=ref(null),form=ref({}),csv=ref(''),csvFile=ref(''),csvPreview=ref(null),loginUser=ref('u1'),password=ref('BuildLedger-demo-2026!'),generatedCredentials=ref(null);
