function pickQuotation(id){const q=quoteOptions.value.find(q=>q.id===id);if(!q)return;form.value.quotationId=q.id;form.value.vendorId=q.vendorId;if(versions.value.find(f=>f.id==='work_order')?.fields.some(f=>f.key==='contract_package'))form.value.data.contract_package=suiteRows(state.value,'rfq',tenantId.value).find(r=>r.id===q.rfqId)?.title||q.description;form.value.description=q.description;form.value.boq=null;}
function raiseFromQuote(q){page.value='orders';open('order');pickQuotation(q.id);form.value.items[0].description=q.description;form.value.items[0].price=String(q.amount/100);}
async function boqChanged(value){const f=Array.isArray(value)?value[0]:value;if(!f){form.value.boq=null;return;}if(f.size>1048576){failure.value='BOQ must be up to 1 MB.';form.value.boq=null;return;}const reader=new FileReader();reader.onload=()=>{form.value.boq={name:f.name,mime:f.type,base64:String(reader.result).split(',')[1],signed:false}};reader.onerror=()=>{failure.value='Could not read the BOQ file.'};reader.readAsDataURL(f);}
function downloadBOQ(o){if(!demo){window.open('/api/boq/'+encodeURIComponent(o.id),'_blank','noopener');return;}if(!o.boq?.base64)return;const bytes=Uint8Array.from(atob(o.boq.base64),x=>x.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:o.boq.mime}));const a=document.createElement('a');a.href=url;a.download=o.boq.name;a.click();URL.revokeObjectURL(url);}
function workApproveLabel(o){return approvalStageLabel(approvalStage(state.value,user.value,tenantId.value,o,state.value.orderEvents.map(e=>({...e,amendmentId:e.orderId})),'work_order'));}
async function orderEvent(o,a){await run('order-transition',{id:o.id,action:a},'Work order approval updated',false);}
const profileVendor=computed(()=>projectVendors.value.find(v=>v.id===profileVendorId.value)||projectVendors.value[0]);
const approvedPurchases=computed(()=>state.value?.purchaseOrders.filter(p=>p.tenantId===tenantId.value&&poStatus(state.value,p)==='Approved'&&can(state.value,user.value,tenantId.value,'view','purchase_order'))||[]);
const formPurchaseOrder=computed(()=>approvedPurchases.value.find(p=>p.id===form.value.purchaseOrderId));
const orders=computed(()=>state.value?.orders.filter(o=>o.tenantId===tenantId.value&&permission('view'))??[]);
const amendments=computed(()=>state.value?.amendments.filter(a=>orders.value.some(o=>o.id===a.orderId))??[]);
const pending=computed(()=>amendments.value.filter(a=>!['Draft','Approved','Rejected'].includes(status(state.value,a))));
const filtered=computed(()=>orders.value.filter(o=>(o.number+' '+o.vendor+' '+o.description).toLowerCase().includes(search.value.toLowerCase())&&(statusFilter.value==='All work orders'||(statusFilter.value==='With pending amendments'?pending.value.some(a=>a.orderId===o.id):!pending.value.some(a=>a.orderId===o.id)))));
const total=computed(()=>orders.value.reduce((n,o)=>n+(effective(state.value,o)??0),0));
const approvedDelta=computed(()=>amendments.value.filter(a=>status(state.value,a)==='Approved').reduce((n,a)=>n+(a.delta??0),0));
const versions=computed(()=>state.value?.forms.filter(f=>f.version===Math.max(...state.value.forms.filter(x=>x.id===f.id).map(x=>x.version)))??[]);
const selection=computed(()=>orders.value.find(o=>o.id===selected.value?.id));
const history=computed(()=>amendments.value.filter(a=>a.orderId===selected.value?.id));
const reras=computed(()=>state.value?.reras.filter(r=>r.tenantId===tenantId.value&&can(state.value,user.value,tenantId.value,'view','rera_account'))??[]);
const bankAccess=key=>fieldAccess(state.value,user.value,tenantId.value,key,'rera_account');
const vendorAccess=key=>user.value?fieldAccess(state.value,user.value,tenantId.value,key,'vendor'):'hidden';
const projectVendors=computed(()=>state.value?.vendors?.filter(v=>v.tenantId===tenantId.value&&!v.deleted&&(!v.onboardingStatus||v.onboardingStatus==='Active')&&can(state.value,user.value,tenantId.value,'view','vendor'))??[]);
const vendorProfile=computed(()=>selection.value?vendorDetails(state.value,user.value,tenantId.value,selection.value):null);
const formVendor=computed(()=>projectVendors.value.find(v=>v.id===form.value.vendorId));
const vendorLabels={name:'Vendor name',trade:'Trade / specialization',contactName:'Contact person',phone:'Phone',email:'Email',gstin:'GSTIN',address:'Address',vendorType:'Vendor type',pan:'PAN',onboardingStatus:'Status',notes:'Notes'};
watch(dialog,next=>{if(next!=='credentials')generatedCredentials.value=null;});
const activity=computed(()=>state.value?.audit.filter(a=>a.tenantId===tenantId.value).slice().reverse()??[]);
const nav=[...['bookings','schedules','corporate'].map((key,i)=>({key,label:['CRM bookings','Payment schedules','Corporate accounts & pay'][i],icon:['mdi-account-details-outline','mdi-calendar-clock-outline','mdi-bank-outline'][i],form:['booking','payment_schedule','corporate_account'][i],group:i===2?'Project controls':'Project workspace'})),{key:'dashboard',label:'CRM dashboard',icon:'mdi-view-dashboard-outline',form:'dashboard',group:'Project workspace'},{key:'projects',label:'Projects',icon:'mdi-domain',superOnly:true,group:'Project workspace'},{key:'expenses',label:'Expenses',icon:'mdi-receipt-text-outline',form:'expense',group:'Project workspace'},{key:'payments',label:'Payments',icon:'mdi-bank-transfer',form:'payment',group:'Project workspace'},{key:'costs',label:'Cost overview',icon:'mdi-chart-box-outline',group:'Project workspace'},{key:'vendors',label:'Vendor Registry',icon:'mdi-truck-outline',form:'vendor',group:'Vendors & Suppliers'},{key:'onboarding',label:'Vendor Onboarding',icon:'mdi-account-plus-outline',form:'vendor_onboarding',group:'Vendors & Suppliers'},{key:'feedback',label:'Vendor Feedback',icon:'mdi-star-outline',form:'vendor_feedback',group:'Vendors & Suppliers'},{key:'orders',label:'Work Orders',icon:'mdi-file-document-outline',group:'Vendors & Suppliers'},{key:'quotations',label:'Vendor Quotations',icon:'mdi-file-compare',form:'quotation_request',group:'Vendors & Suppliers'},{key:'vendorreports',label:'Reporting',icon:'mdi-chart-box-outline',form:'vendor_reporting',group:'Vendors & Suppliers'},{key:'purchases',label:'Purchase orders',icon:'mdi-cart-outline',group:'Project controls'},{key:'inventory',label:'Inventory',icon:'mdi-package-variant-closed',group:'Project controls'},{key:'approvals',label:'Approval inbox',icon:'mdi-check-decagram-outline',group:'Project controls'},{key:'rera',label:'RERA accounts',icon:'mdi-office-building-outline',group:'Project controls'},{key:'access',label:'Users & roles',icon:'mdi-account-key-outline',group:'Configuration'},{key:'forms',label:'Form configuration',icon:'mdi-form-select',group:'Configuration'},{key:'audit',label:'Audit history',icon:'mdi-history',group:'Configuration'}];
const visibleNav=computed(()=>nav.filter(i=>(!i.superOnly||user.value?.superuser)&&(i.key!=='costs'||canCost(state.value,user.value,tenantId.value))&&(!i.form||can(state.value,user.value,tenantId.value,'view',i.form))));
const navGroups=computed(()=>[...new Set(visibleNav.value.map(n=>n.group))].map(name=>({name,items:visibleNav.value.filter(n=>n.group===name)})));
const workPending=computed(()=>orders.value.filter(o=>o.workflowEnabled&&!['Approved','Rejected'].includes(orderStatus(state.value,o))));
const quotationPending=computed(()=>suiteRows(state.value,'award',tenantId.value).filter(a=>!['Approved','Rejected','Draft'].includes(suiteStatus(state.value,a))));
const projectCost=computed(()=>state.value?.costs?.find(c=>c.tenantId===tenantId.value)?.total??total.value+purchaseCost(state.value,tenantId.value));
const financePending=computed(()=>[...(state.value?.expenses||[]),...(state.value?.payments||[])].filter(d=>d.tenantId===tenantId.value&&!['Draft','Approved','Rejected'].includes(financeStatus(state.value,d))));
const purchasePending=computed(()=>state.value?.purchaseOrders.filter(p=>p.tenantId===tenantId.value&&!['Draft','Approved','Rejected'].includes(poStatus(state.value,p))).length||0);
const projectCostVisible=computed(()=>canCost(state.value,user.value,tenantId.value));
