const roleAssignmentCount=id=>state.value.memberships.filter(m=>m.roleIds.includes(id)).length;
const who=id=>state.value?.users.find(u=>u.id===id)?.name??'Unknown';
const date=s=>new Date(s).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});
const badge=s=>s==='Approved'?'green':s==='Rejected'?'red':s==='Draft'?'gray':'amber';
const orderFor=a=>orders.value.find(o=>o.id===a.orderId);
async function refresh(){state.value=await load(userId.value);if(!demo&&state.value.currentUserId)userId.value=state.value.currentUserId;if(!tenant.value)tenantId.value=tenants.value[0]?.id||'';if(!visibleNav.value.some(n=>n.key===page.value))page.value=visibleNav.value[0]?.key||'orders';}
async function run(kind,data,message,close=true){busy.value=true;failure.value='';try{const r=await command(kind,data,user.value,tenantId.value);if(kind==='preview'){csvPreview.value=r;return;}await refresh();toast.value=message;if(r.credentials){dialog.value='credentials';generatedCredentials.value=r.credentials;}else if(close)dialog.value='';return r;}catch(e){failure.value=e.message;}finally{busy.value=false;}}
async function signin(){busy.value=true;try{const result=await login(loginUser.value,password.value);userId.value=result.userId;page.value='dashboard';await refresh();}catch(e){failure.value=e.message;}finally{busy.value=false;}}
async function signout(){await logout();userId.value='';state.value=null;}
async function switchUser(){drawer.value=false;failure.value='';await refresh();}
function open(kind,existing){failure.value='';dialog.value=kind;if(kind==='order')form.value={number:'WO-'+tenant.value.code+'-'+String(orders.value.length+1).padStart(3,'0'),vendorId:'',description:'',quotationId:'',boq:null,orderDate:new Date().toISOString().slice(0,10),purchaseOrderId:'',items:[{description:'',unit:'unit',quantity:'1',price:'',startDate:'',endDate:''}],formId:'work_order',data:{}};
else if(kind==='vendor')form.value=existing?{...JSON.parse(JSON.stringify(existing)),formVersion:existing.vendorFormVersion,data:{...(existing.vendorData||{})}}:{...Object.fromEntries(vendorFields.map(k=>[k,''])),data:{}};
else if(kind==='vendor-delete'||kind==='user-credentials'||kind==='role-delete')form.value={id:existing.id,name:existing.name};
else if(kind==='user-create')form.value={name:'',username:'',title:'',projectRoles:Object.fromEntries(state.value.tenants.filter(t=>!t.deleted).map(t=>[t.id,[]]))};
else if(kind==='amend')form.value={orderId:existing.id,amount:'',reason:'',data:{...existing.data}};
else if(kind==='role')form.value=existing?JSON.parse(JSON.stringify(existing)):{name:'',stage:'',permissions:{work_order:{actions:['view'],fields:{amount:'hidden',description:'view',reason:'view'}}}};
else if(kind==='form'){form.value=existing?JSON.parse(JSON.stringify(existing)):{name:'',fields:[]};form.value.itemFields ||= [];}
else if(kind==='membership-remove')form.value={userId:existing.id,name:existing.name,roleIds:[]};
else if(kind==='membership')form.value={userId:existing.id,roleIds:state.value.memberships.find(m=>m.userId===existing.id&&m.tenantId===tenantId.value)?.roleIds.slice()??[]};
else if(kind==='import'){csv.value='';csvFile.value='';csvPreview.value=null;}
else form.value={data:{}};}
function itemAmount(i){return Number((BigInt(quantity(i.quantity))*BigInt(cents(i.price))+500n)/1000n);}
function draftWorkTotal(){return form.value.items.reduce((n,i)=>n+itemAmount(i),0);}
function workEstimate(i){try{return money(i?itemAmount(i):draftWorkTotal());}catch{return 'Complete quantity and rate';}}
async function saveOrder(){try{const items=form.value.items.map(i=>({itemData:i.itemData||{},description:i.description,unit:i.unit,startDate:i.startDate,endDate:i.endDate,quantityMilli:quantity(i.quantity),rate:cents(i.price)}));await run('order',{...form.value,items,base:draftWorkTotal()},'Work order created');}catch(e){failure.value=e.message;}}
async function saveAmend(){try{await run('amend',{orderId:form.value.orderId,delta:cents(form.value.amount),reason:form.value.reason,data:form.value.data},'Draft amendment saved');}catch(e){failure.value=e.message;}}
function showOrder(o){selected.value=o;profileVendorId.value=o.vendorId;drawer.value=true;}
function canAct(a,act){if(!permission(act))return false;const st=status(state.value,a);if(act==='submit')return st==='Draft'&&(a.createdBy===userId.value||user.value.superuser);if(a.createdBy===userId.value&&!user.value.superuser)return false;if(act==='review')return st==='Review';if(act==='reject')return !['Draft','Approved','Rejected'].includes(st);if(act==='approve')return canApprove(state.value,user.value,tenantId.value,a);return false;}
async function event(a,action){await run('transition',{id:a.id,action},action==='approve'?'Approval recorded':action==='review'?'Review completed':action==='submit'?'Submitted for approval':'Amendment rejected',false);}
async function fileChanged(e){const f=e.target.files?.[0];if(!f)return;csvFile.value=f.name;csvPreview.value=null;if(f.size>1000000){failure.value='CSV must be smaller than 1 MB.';return;}csv.value=await f.text();}
function downloadCSV(){const data='work_order,delta_including_tax,reason\n'+(orders.value[0]?.number??'WO-SKY-001')+',200000,Additional approved scope\n';const url=URL.createObjectURL(new Blob([data],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='work-order-amendments.csv';a.click();URL.revokeObjectURL(url);}
async function copyCredentials(){try{await navigator.clipboard.writeText('Username: '+generatedCredentials.value.username+'\nPassword: '+generatedCredentials.value.password);toast.value='Credentials copied';}catch{failure.value='Copy the username and password from the fields below.';}}
function roleFieldKeys(){const id=form.value.permissionForm||'work_order';const core={...extensionFields,work_order:workOrderFields,purchase_order:purchaseFields,inventory:inventoryFields,vendor:vendorFields,vendor_onboarding:vendorFields,expense:financeFields,payment:financeFields,cost_overview:['amount'],rera_account:['number','bank','ifsc','label'],project:['name','code','location'],dashboard:['progress','cash','sales','budget'],vendor_reporting:['amount','ratings','reference'],...Object.fromEntries(Object.entries(suiteFields).map(([k,v])=>[formForKind(k),v]))};return [...new Set([...(core[id]||fieldKeys),...(versions.value.find(f=>f.id===id)?.fields.map(f=>f.key)||[]),...(versions.value.find(f=>f.id===id)?.itemFields||[]).map(f=>'item_'+f.key)])];}
function customFields(){return versions.value.find(f=>f.id===form.value.formId)?.fields??[];}
onMounted(async()=>{if(demo)await refresh();else {try{await refresh();const me=state.value.currentUserId;userId.value=me;}catch{state.value=null;}}});
</script>
<template>
<v-app><div v-if="!user" class="login-screen"><div class="login-card"><img class="login-logo" src="/vrise-logo.png" alt="VRISE" width="1986" height="792"><h1>Construction ERP</h1><p>Construction, accounted for.</p><v-text-field v-model="loginUser" label="Username" autocomplete="username" @keyup.enter="signin"/><v-text-field v-model="password" type="password" label="Password" @keyup.enter="signin"/><v-alert v-if="failure" type="error" class="mb-4">{{failure}}</v-alert><v-btn color="primary" block size="large" :loading="busy" @click="signin">Sign in</v-btn><p class="small muted">Sign in with the credentials supplied by your project administrator.</p></div></div>
<div v-else class="app-shell">
<aside :class="['sidebar',{'mobile-open':mobileMenu}]"><a class="brand" href="#" @click.prevent="page='orders'"><span class="brand-logo-frame"><img class="brand-logo" src="/vrise-logo.png" alt="VRISE" width="1986" height="792"></span><span class="brand-sub">CONSTRUCTION ERP</span></a><div class="project-label">PROJECT WORKSPACE</div><button class="project-current" @click="open('project-switch')"><span class="project-monogram">{{tenant?.code??'—'}}</span><span><strong>{{tenant?.name??'No project access'}}</strong><small>{{tenant?.location}}</small></span><v-icon size="20">mdi-chevron-down</v-icon></button>
<nav><div v-for="group in navGroups" :key="group.name" class="nav-group"><div class="nav-group-label">{{group.name}}</div><button v-for="item in group.items" :key="item.key" :class="{active:page===item.key}" @click="page=item.key;drawer=false;mobileMenu=false;failure=''" ><v-icon size="21">{{item.icon}}</v-icon><span>{{item.label}}</span><span v-if="item.key==='approvals'&&(pending.length+purchasePending+financePending.length+workPending.length+quotationPending.length)" class="nav-count">{{pending.length+purchasePending+financePending.length+workPending.length+quotationPending.length}}</span></button></div></nav>
<div class="sidebar-footer"><div class="workspace-pill"><v-icon size="17">mdi-shield-check-outline</v-icon> {{user.superuser?'Platform superuser':'Project access'}}</div><p>{{user.superuser?'Manage every project from one workspace.':roleList(state,user,tenantId).map(r=>r.name).join(' · ')||'No assigned roles'}}</p><button v-if="user.superuser" class="new-project" @click="open('tenant')"><v-icon size="18">mdi-plus</v-icon> Add project</button></div></aside>
<div v-if="mobileMenu" class="mobile-scrim" @click="mobileMenu=false"></div>
<div class="main-area"><header class="topbar"><button class="mobile-toggle" aria-label="Open navigation" @click="mobileMenu=!mobileMenu"><v-icon>mdi-menu</v-icon></button><div class="breadcrumb">Projects <v-icon size="16">mdi-chevron-right</v-icon><span>{{tenant?.name}}</span></div><div class="topbar-right"><span class="demo-badge" v-if="demo">Interactive sample</span><v-icon size="21" color="bronze">mdi-shield-lock-outline</v-icon><div class="account"><span class="avatar">{{user.name.split(' ').map(x=>x[0]).slice(0,2).join('')}}</span><div><strong>{{user.name}}</strong><small>{{user.title}}</small></div><v-menu v-if="demo"><template #activator="{props}"><v-btn v-bind="props" icon="mdi-chevron-down" size="small" variant="text" aria-label="Switch sample user"/></template><v-list><v-list-subheader>Switch sample account</v-list-subheader><v-list-item v-for="u in state.users" :key="u.id" :title="u.name" :subtitle="u.title" @click="userId=u.id;switchUser()"/><v-divider/><v-list-item title="Sign out / test credentials" prepend-icon="mdi-logout" @click="signout"/></v-list></v-menu><v-btn v-else icon="mdi-logout" variant="text" size="small" aria-label="Sign out" @click="signout"/></div></div></header>
<main><div v-if="demo" class="sample-note"><v-icon size="18">mdi-flask-outline</v-icon><span>Sample data · changes reset on refresh. Switch accounts to try both approval stages and restricted access.</span></div>
<v-alert v-if="failure&&!dialog" type="error" variant="tonal" closable @click:close="failure=''" class="mb-5">{{failure}}</v-alert>
<div class="page-heading"><div><div class="eyebrow">{{tenant?.code||'PROJECT'}} / {{page==='orders'?'FINANCIAL CONTROL':'WORKSPACE'}}</div><h1>{{titles[page]}}</h1><p>{{page==='dashboard'?'Work progress, cash collections, sales and project budget.':page==='quotations'?'Collect bids, compare criteria and approve your vendor selection.':page==='feedback'?'Retained vendor performance assessments.':page==='vendorreports'?'Vendor commitments, performance and purchasing purpose.':page==='expenses'?'Consultancy, payroll, materials and site overheads with approval history.':page==='payments'?'Validate vendor invoices, record settlements and track outstanding balances.':page==='costs'?'Approved project commitments and additional expenses for Admin and Superuser.':page==='onboarding'?'Prepare vendor profiles, submit them and activate them for new orders.':page==='projects'?'Manage project tenants with superuser-only controls.':page==='purchases'?'Purchased materials, rental costs and superuser-controlled approvals.':page==='inventory'?'Receive, use and carry unused purchased materials between projects.':page==='orders'?'Track committed value, scope changes and every approval.':page==='approvals'?'Review scope changes before they enter the committed total.':page==='vendors'?'Project contacts, trades and work-order references.':page==='rera'?'Project bank accounts, unique across the entire platform.':page==='access'?'Shared role definitions. Project-specific user assignments.':page==='forms'?'Versioned financial templates, shared across every project.':'A chronological record of project and configuration changes.'}}</p></div><div class="heading-actions" v-if="page==='orders'"><v-btn variant="outlined" prepend-icon="mdi-upload-outline" v-if="permission('amend')&&editable" @click="open('import')">Import CSV</v-btn><v-btn color="primary" prepend-icon="mdi-plus" v-if="creatable" @click="open('order')">New work order</v-btn></div><v-btn v-if="page==='vendors'&&user.superuser" color="primary" prepend-icon="mdi-plus" @click="open('vendor')">Add vendor</v-btn><v-btn v-if="page==='access'&&user.superuser" color="primary" prepend-icon="mdi-account-plus-outline" @click="open('user-create')">Add user</v-btn><v-btn v-if="page==='rera'&&user.superuser" color="primary" prepend-icon="mdi-plus" @click="open('rera')">Add RERA account</v-btn><v-btn v-if="page==='forms'&&user.superuser" color="primary" prepend-icon="mdi-plus" @click="open('form')">Create form</v-btn></div>
<PaymentSchedulePanel v-if="['bookings','schedules','corporate'].includes(page)" :state="state" :user="user" :tenant-id="tenantId" :page="page" :execute="run" :busy="busy" :failure="failure"/><DashboardPanel v-if="page==='dashboard'" :key="tenantId" :state="state" :user="user" :tenant-id="tenantId" :execute="run" :busy="busy" :failure="failure"/><VendorSuitePanel v-else-if="['quotations','feedback','vendorreports'].includes(page)" :key="tenantId+page" :state="state" :user="user" :tenant-id="tenantId" :page="page" :execute="run" :busy="busy" :failure="failure" @raise-order="raiseFromQuote"/><ProjectsPanel v-else-if="page==='projects'&&user.superuser" :state="state" :user="user" :busy="busy" :execute="run" :failure="failure" @select="id=>{tenantId=id;page='orders'}"/><ProcurementPanel v-else-if="['purchases','inventory'].includes(page)" :key="tenantId+'-'+page" :state="state" :user="user" :tenant-id="tenantId" :page="page" :busy="busy" :execute="run" :failure="failure" :initial-order-id="purchaseContextId"/>
<FinancePanel v-else-if="['expenses','payments'].includes(page)" :key="tenantId+'-'+page" :state="state" :user="user" :tenant-id="tenantId" :page="page" :execute="run" :busy="busy" :failure="failure"/><CostPanel v-else-if="page==='costs'" :state="state" :user="user" :tenant-id="tenantId"/><OnboardingPanel v-else-if="page==='onboarding'" :key="tenantId" :state="state" :user="user" :tenant-id="tenantId" :execute="run" :busy="busy" :failure="failure"/><template v-else-if="page==='orders'"><div v-if="projectCostVisible" class="workflow-banner"><v-icon color="primary">mdi-wallet-outline</v-icon><div><strong>Total committed project cost · {{money(projectCost)}}</strong><p>Work orders + approved purchases, rentals and additional expenses. Linked expenses and payments add no cost again.</p></div></div><div class="stats-grid"><div class="stat-card primary-stat"><div class="stat-label">Work order committed value<v-icon size="21">mdi-wallet-outline</v-icon></div><strong>{{showAmounts?money(total):'Restricted'}}</strong><span>Including tax · approved changes only</span></div><div class="stat-card"><div class="stat-label">Work orders<v-icon size="21">mdi-file-document-multiple-outline</v-icon></div><strong>{{orders.length.toString().padStart(2,'0')}}</strong><span>{{reras.length}} visible RERA bank accounts</span></div><div class="stat-card"><div class="stat-label">Awaiting approval<v-icon size="21">mdi-clock-outline</v-icon></div><strong>{{pending.length.toString().padStart(2,'0')}}<span class="metric-chip">Needs review</span></strong><span>Changes excluded from committed value</span></div><div class="stat-card"><div class="stat-label">Approved amendments<v-icon size="21">mdi-source-branch</v-icon></div><strong>{{showAmounts?(approvedDelta>=0?'+':'')+money(approvedDelta):'Restricted'}}</strong><span>{{amendments.filter(a=>status(state,a)==='Approved').length}} amendments in the record</span></div></div>
<section v-if="projectVendors.length" class="panel mb-6"><div class="panel-top"><h2>Vendor profile</h2><v-select v-model="profileVendorId" :model-value="profileVendor?.id" :items="projectVendors.map(v=>({title:v.name,value:v.id}))" label="View project vendor" density="compact" hide-details class="vendor-picker"/></div><VendorProfile :profile="profileVendor" :editable="user.superuser" @edit="open('vendor',profileVendor)"/></section>
<section class="panel"><div class="panel-top"><div><h2>Project work orders <span class="count-pill">{{orders.length}}</span></h2><p>One current total. A complete revision trail.</p></div><span class="quiet-label"><v-icon size="16">mdi-lock-outline</v-icon> Approved history is retained</span></div><div class="table-toolbar"><v-text-field v-model="search" prepend-inner-icon="mdi-magnify" placeholder="Search work orders or vendors" aria-label="Search work orders" hide-details density="compact" class="search-field"/><v-select v-model="statusFilter" :items="['All work orders','With pending amendments','Without pending amendments']" aria-label="Filter work orders" hide-details density="compact" class="status-select"/></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>WORK ORDER / VENDOR</th><th>SCOPE</th><th v-if="showAmounts" class="align-right">CURRENT VALUE</th><th>ORDER APPROVAL / AMENDMENTS</th><th>LAST UPDATED</th><th></th></tr></thead><tbody><tr v-for="o in filtered" :key="o.id" @click="showOrder(o)"><td><button class="order-link" @click.stop="showOrder(o)">{{o.number}}</button><span class="cell-secondary">{{o.vendor}}</span></td><td class="scope-cell">{{o.description}}</td><td v-if="showAmounts" class="align-right"><strong>{{money(effective(state,o))}}</strong><span class="cell-secondary">Including tax</span></td><td><span v-if="o.workflowEnabled" class="status-badge amber">{{orderStatus(state,o)}}</span><span :class="['status-badge',pending.some(a=>a.orderId===o.id)?'amber':'green']">{{pending.some(a=>a.orderId===o.id)?'Approval pending':'Up to date'}}</span><span class="cell-secondary">{{amendments.filter(a=>a.orderId===o.id).length}} revisions</span></td><td>{{date(amendments.filter(a=>a.orderId===o.id).at(-1)?.createdAt??o.createdAt)}}</td><td><v-icon size="20" color="bronze">mdi-chevron-right</v-icon></td></tr><tr v-if="!filtered.length"><td colspan="6" class="empty-state">{{permission('view')?'No work orders match this view.':'Your project roles do not grant access to work orders.'}}</td></tr></tbody></table></div><div class="table-bottom">{{filtered.length}} work orders<span><v-icon size="16">mdi-information-outline</v-icon> Pending amendments never change the current total</span></div></section>
<div class="lower-grid"><section class="panel"><div class="panel-top"><h2>Approval queue</h2><button class="text-button" @click="page='approvals'">View inbox</button></div><div v-if="!pending.length" class="empty-state">No amendments awaiting approval.</div><button v-for="a in pending.slice(0,3)" :key="a.id" class="queue-row" @click="showOrder(orderFor(a))"><span class="queue-icon"><v-icon size="22">mdi-file-clock-outline</v-icon></span><span class="queue-copy"><strong>{{orderFor(a)?.number}}</strong><small>{{a.reason}}</small></span><span class="queue-value"><strong v-if="showAmounts">{{a.delta>=0?'+':''}}{{money(a.delta)}}</strong><small>{{status(state,a)}}</small></span></button></section><section class="panel"><div class="panel-top"><h2>Recent activity</h2><button class="text-button" @click="page='audit'">View history</button></div><div v-for="a in activity.slice(0,3)" :key="a.id" class="activity-row"><span class="activity-dot"></span><div><strong>{{a.action}}</strong><p>{{a.target}} · {{who(a.actorId)}}</p><small>{{date(a.at)}}</small></div></div><div v-if="!activity.length" class="empty-state">Project activity will appear here.</div></section></div></template>
<template v-else-if="page==='approvals'"><div v-if="workPending.length||quotationPending.length" class="workflow-banner"><v-icon color="primary">mdi-file-check-outline</v-icon><div><strong>{{workPending.length}} work orders · {{quotationPending.length}} quotation selections awaiting action</strong><p>Quotation selection precedes work-order approval. Labour work orders require an approved linked PO.</p></div><v-btn variant="outlined" @click="page='quotations'">Quotations</v-btn><v-btn variant="outlined" @click="page='orders'">Work orders</v-btn></div><div v-if="financePending.length" class="workflow-banner"><v-icon color="primary">mdi-receipt-text-outline</v-icon><div><strong>{{financePending.length}} expenses and payments awaiting approval</strong><p>Open the financial register to review and approve each record.</p></div><v-btn v-if="can(state,user,tenantId,'view','expense')" variant="outlined" @click="page='expenses'">Expenses</v-btn><v-btn v-if="can(state,user,tenantId,'view','payment')" variant="outlined" @click="page='payments'">Payments</v-btn></div><div v-if="purchasePending" class="workflow-banner"><v-icon color="primary">mdi-cart-outline</v-icon><div><strong>{{purchasePending}} purchase orders awaiting approval</strong><p>Review and approve them in Purchase orders.</p></div><v-btn variant="outlined" color="primary" @click="page='purchases'">Open purchase orders</v-btn></div><div class="workflow-banner"><v-icon color="primary">mdi-check-decagram-outline</v-icon><div><strong>Superuser direct approval · Two-person approval for other users</strong><p>Superuser submissions need only superuser approval. Other submissions require Admin + Superuser or Superuser + Finance, after review.</p></div></div><section class="panel"><div class="panel-top"><h2>Pending amendments <span class="count-pill">{{pending.length}}</span></h2><span class="quiet-label">Current account: {{user.name}}</span></div><div class="approval-list"><article v-for="a in [...pending,...amendments.filter(a=>status(state,a)==='Draft')]" :key="a.id" class="approval-card"><div class="approval-head"><button class="order-link" @click="showOrder(orderFor(a))">{{orderFor(a)?.number}}</button><span :class="['status-badge',badge(status(state,a))]">{{status(state,a)}}</span></div><h3>{{a.reason}}</h3><p class="small muted mb-3">{{approvalRequirement(a)}}</p><div class="approval-meta">{{who(a.createdBy)}} · {{date(a.createdAt)}}<strong v-if="showAmounts" :class="a.delta<0?'negative':'positive'">{{a.delta>=0?'+':''}}{{money(a.delta)}}</strong></div><div class="approval-actions"><v-btn v-if="canAct(a,'submit')" size="small" color="primary" :loading="busy" @click="event(a,'submit')">Submit for approval</v-btn><v-btn v-if="canAct(a,'review')" size="small" color="primary" :loading="busy" @click="event(a,'review')">Complete review</v-btn><v-btn v-if="canAct(a,'approve')" size="small" color="primary" :loading="busy" @click="event(a,'approve')">{{approvalStageLabel(approvalStage(state,user,tenantId,a,state.events))}}</v-btn><v-btn v-if="canAct(a,'reject')" size="small" variant="outlined" color="error" :loading="busy" @click="event(a,'reject')">Reject</v-btn><span v-if="!['submit','review','approve','reject'].some(x=>canAct(a,x))" class="small muted">{{a.createdBy===userId?'Waiting for another authorized user.':'Your account has no action at this stage.'}}</span></div></article><div v-if="!pending.length&&!amendments.some(a=>status(state,a)==='Draft')" class="empty-state">The approval inbox is clear.</div></div></section></template>
<template v-else-if="page==='vendors'"><section class="panel"><div class="panel-top"><div><h2>{{tenant?.name}} vendors <span class="count-pill">{{projectVendors.length}}</span></h2><p>The same vendor may have a separate profile in another project.</p></div></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>VENDOR / TRADE</th><th>CONTACT PERSON</th><th>PHONE / EMAIL</th><th>WORK ORDERS</th><th v-if="user.superuser">ACTIONS</th></tr></thead><tbody><tr v-for="v in projectVendors" :key="v.id"><td><strong>{{v.name||'Restricted name'}}</strong><span class="cell-secondary">{{v.trade||'—'}}</span></td><td>{{v.contactName||'—'}}</td><td>{{v.phone||'—'}}<span class="cell-secondary">{{v.email||'—'}}</span></td><td>{{orders.filter(o=>o.vendorId===v.id).length}}</td><td v-if="user.superuser"><v-btn variant="text" color="primary" size="small" @click="open('vendor',v)">Edit</v-btn><v-btn variant="text" color="error" size="small" @click="open('vendor-delete',v)">Delete</v-btn></td></tr><tr v-if="!projectVendors.length"><td colspan="5" class="empty-state">No vendors available with your current project permissions.</td></tr></tbody></table></div></section></template>
<template v-else-if="page==='rera'"><section class="panel"><div class="panel-top"><h2>{{tenant?.name}} bank accounts</h2><span class="quiet-label">Global uniqueness enforced</span></div><div v-for="r in reras" :key="r.id" class="rera-row"><span class="rera-icon"><v-icon>mdi-office-building-marker-outline</v-icon></span><div><h3>{{bankAccess('number')==='hidden'?'Account number restricted':r.number}}</h3><p>{{bankAccess('bank')==='hidden'?'Bank restricted':r.bank}} · {{bankAccess('ifsc')==='hidden'?'IFSC restricted':r.ifsc}}</p><p v-if="bankAccess('label')!=='hidden'">{{r.label}}</p><div v-for="(v,k) in r.data" :key="k" class="small muted">{{k}}: {{v}}</div></div><span class="status-badge green">Registered</span></div><div v-if="!reras.length" class="empty-state">No bank accounts available with your current project permissions.</div></section></template>
<template v-else-if="page==='access'"><section class="panel"><div class="panel-top"><h2>Project user assignments</h2><span class="quiet-label">Users can belong to multiple projects</span></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>USER</th><th>PROJECT ROLES</th><th></th></tr></thead><tbody><tr v-for="u in state.users" :key="u.id"><td><strong>{{u.name}}</strong><span class="cell-secondary">{{u.title}} · {{u.username}}</span></td><td><span v-if="u.superuser" class="status-badge blue">All projects · Superuser</span><template v-else><span v-for="r in roleList(state,u,tenantId)" :key="r.id" class="role-pill">{{r.name}}</span><span v-if="!roleList(state,u,tenantId).length" class="muted">No project roles</span></template></td><td><v-btn v-if="user.superuser&&!u.superuser" variant="text" color="primary" size="small" @click="open('membership',u)" :disabled="!tenantId">{{roleList(state,u,tenantId).length?'Edit roles':'Assign roles'}}</v-btn><v-btn v-if="user.superuser&&!u.superuser&&roleList(state,u,tenantId).length" variant="text" color="error" size="small" @click="open('membership-remove',u)">Remove roles</v-btn><v-btn v-if="user.superuser&&!u.superuser" variant="text" color="primary" size="small" @click="open('user-credentials',u)">Generate credentials</v-btn></td></tr></tbody></table></div></section><section class="panel mt-6"><div class="panel-top"><div><h2>Shared role definitions</h2><p>Permission updates apply to this role across all projects.</p></div><v-btn v-if="user.superuser" color="primary" variant="outlined" prepend-icon="mdi-plus" @click="open('role')">Add role</v-btn></div><div class="role-grid"><article v-for="r in state.roles" :key="r.id" class="role-card"><div class="role-card-head"><v-icon color="primary">mdi-account-key-outline</v-icon><div v-if="user.superuser" class="role-actions"><v-btn prepend-icon="mdi-pencil-outline" variant="text" size="small" :aria-label="'Edit role '+r.name" @click="open('role',r)">Edit</v-btn><v-btn prepend-icon="mdi-delete-outline" variant="text" color="error" size="small" :aria-label="'Delete role '+r.name" @click="open('role-delete',r)">Delete</v-btn></div></div><h3>{{r.name}}</h3><p>{{r.stage?r.stage+' approval stage':'No approval stage'}}</p><div class="permission-chips"><span v-for="a in r.permissions.work_order?.actions??[]" :key="a">{{a}}</span></div><div class="field-note">Financial amount: <strong>{{r.permissions.work_order?.fields?.amount??'hidden'}}</strong></div></article></div></section></template>
<template v-else-if="page==='forms'"><div class="workflow-banner"><v-icon color="primary">mdi-file-document-edit-outline</v-icon><div><strong>Publish new versions without rewriting existing records</strong><p>Core amount and approval rules stay enforced. Add text, number or date fields to financial templates.</p></div></div><section class="panel"><div class="form-grid"><article v-for="f in versions.filter(f=>!['dashboard','vendor_reporting','cost_overview'].includes(f.id))" :key="f.id" class="form-card"><div class="approval-head"><span class="form-icon"><v-icon>mdi-form-select</v-icon></span><span class="status-badge blue">Version {{f.version}}</span></div><h2>{{f.name}}</h2><p>{{f.id==='work_order'?'Core work order template':'Versioned record fields and permissions'}}</p><ul><li v-if="f.id==='work_order'">Work order number, vendor, scope & total</li><li v-for="field in f.fields" :key="field.key">{{field.label}} <small>{{field.type}}{{field.required?' · required':''}}</small></li></ul><v-btn v-if="user.superuser" color="primary" variant="outlined" prepend-icon="mdi-pencil-outline" @click="open('form',f)">Edit & publish version</v-btn><small class="version-footnote">{{state.forms.filter(x=>x.id===f.id).length}} retained versions</small></article></div></section></template>
<template v-else-if="page==='audit'"><section class="panel"><div class="panel-top"><h2>Project activity</h2><span class="quiet-label"><v-icon size="16">mdi-lock-outline</v-icon> Append-only history</span></div><div class="table-scroll"><table class="orders-table"><thead><tr><th>DATE</th><th>ACTION</th><th>RECORD</th><th>USER</th></tr></thead><tbody><tr v-for="a in activity" :key="a.id"><td>{{date(a.at)}}<span class="cell-secondary">{{new Date(a.at).toLocaleTimeString('en-IN')}}</span></td><td>{{a.action}}</td><td>{{a.target}}</td><td>{{who(a.actorId)}}</td></tr><tr v-if="!activity.length"><td colspan="4" class="empty-state">No recorded activity for this project.</td></tr></tbody></table></div></section></template>
<footer class="page-footer"><span>VRISE</span><span>{{tenant?.name}} · INR · Totals include tax</span></footer>
</main></div>
</div>
<v-navigation-drawer v-if="user" v-model="drawer" temporary location="right" width="860" class="detail-drawer"><template v-if="selection"><div class="detail-top"><div><div class="eyebrow">WORK ORDER DETAILS</div><h2>{{selection.number}}</h2><p>{{selection.vendor}}</p></div><v-btn icon="mdi-close" variant="text" aria-label="Close details" @click="drawer=false"/></div><div class="detail-content"><section v-if="vendorProfile" class="vendor-brief"><div class="approval-head"><h3>Vendor information</h3><span class="status-badge blue">{{state.vendors?.some(v=>v.id===selection.vendorId&&!v.deleted)?'Project profile':'Retained record'}}</span></div><dl><template v-for="(v,k) in vendorProfile" :key="k"><dt>{{vendorLabels[k]||k}}</dt><dd>{{v||'—'}}</dd></template></dl><v-btn v-if="user.superuser&&state.vendors?.some(v=>v.id===selection.vendorId&&!v.deleted)" variant="text" color="primary" size="small" prepend-icon="mdi-pencil-outline" @click="open('vendor',state.vendors.find(v=>v.id===selection.vendorId))">Edit vendor details</v-btn><details v-if="user.superuser&&selection.vendorSnapshot"><summary>Details recorded when issued</summary><dl><template v-for="k in vendorFields" :key="k"><dt>{{vendorLabels[k]||k}}</dt><dd>{{selection.vendorSnapshot[k]||'—'}}</dd></template></dl></details></section><p class="scope-detail">{{selection.description}}</p><div class="contract-links"><span>Quotation: {{selection.quotationNumber||'Legacy · not recorded'}}</span><span>Contract: {{selection.contractType||'Legacy · not recorded'}}</span><span v-if="selection.workflowEnabled">Order approval: {{orderStatus(state,selection)}}</span></div><div v-if="selection.boq" class="boq-box"><strong>Signed BOQ · {{selection.boq.name}}</strong><p>Retained attachment supplied by the order creator.</p><v-btn variant="outlined" size="small" @click="downloadBOQ(selection)">Download BOQ</v-btn></div><section class="mt-5"><h3>Linked purchase orders</h3><div v-for="p in state.purchaseOrders.filter(p=>p.orderId===selection.id)" :key="p.id" class="queue-row"><strong>{{p.number}} · {{poStatus(state,p)}}</strong><span class="small">{{p.purpose}}</span></div><p v-if="!state.purchaseOrders.some(p=>p.orderId===selection.id)" class="small muted mt-3">No linked PO. {{selection.contractType==='Labour'?'An approved PO is required before work-order approval.':''}}</p><v-btn v-if="can(state,user,tenantId,'create','purchase_order')" variant="outlined" class="mt-3" @click="purchaseContextId=selection.id;drawer=false;page='purchases'">Raise linked purchase order</v-btn></section><div v-if="selection.workflowEnabled" class="approval-actions"><v-btn v-for="a in ['submit','review','approve','reject'].filter(a=>canSuiteAct(state,user,tenantId,selection,a,true))" :key="a" :color="a==='reject'?'error':'primary'" :loading="busy" @click="orderEvent(selection,a)">{{a==='approve'?workApproveLabel(selection):a==='review'?'Complete review':a==='submit'?'Submit work order':'Reject'}}</v-btn></div><div v-for="e in state.orderEvents.filter(e=>e.orderId===selection.id)" :key="e.id" class="event-line">{{e.action}} {{e.stage}} · {{who(e.actorId)}} · {{new Date(e.at).toLocaleString('en-IN')}}</div><WorkOrderItems :order="selection" :modes="workModes"/><ItemFields v-for="(line,index) in selection.items" :key="index" :state="state" :user="user" :tenant-id="tenantId" form-id="work_order" :record="line" :version="selection.formVersion" readonly/><div class="detail-total"><span>Current effective value · including tax</span><strong>{{showAmounts?money(effective(state,selection)):'Restricted'}}</strong><small>Original value {{showAmounts?money(selection.base):'restricted'}} · approved amendments only</small></div><div class="custom-data"><span v-for="(v,k) in Object.fromEntries(Object.entries(selection.data||{}).filter(([key])=>access(key)!=='hidden'))" :key="k"><small>{{state.forms.find(f=>f.id===selection.formId&&f.version===selection.formVersion)?.fields.find(f=>f.key===k)?.label??k}}</small><strong>{{v||'—'}}</strong></span></div><v-btn v-if="permission('amend')&&editable&&orderStatus(state,selection)==='Approved'" color="primary" block prepend-icon="mdi-plus" @click="open('amend',selection)">Create amendment</v-btn><div class="history-title"><h3>Revision history</h3><span>{{history.length}} amendments</span></div><div class="history-card original"><div class="approval-head"><strong>Original work order</strong><span class="status-badge gray">Original</span></div><p>{{date(selection.createdAt)}} · {{who(selection.createdBy)}}</p><strong v-if="showAmounts">{{money(selection.base)}}</strong></div><article v-for="(a,i) in history" :key="a.id" class="history-card"><div class="approval-head"><strong>Amendment {{i+1}}</strong><span :class="['status-badge',badge(status(state,a))]">{{status(state,a)}}</span></div><h4>{{a.reason}}</h4><p>{{date(a.createdAt)}} · {{who(a.createdBy)}}</p><strong v-if="showAmounts" :class="a.delta<0?'negative':'positive'">{{a.delta>=0?'+':''}}{{money(a.delta)}}</strong><div class="event-line" v-for="e in state.events.filter(e=>e.amendmentId===a.id)" :key="e.id"><v-icon size="15">mdi-check-circle-outline</v-icon><span>{{e.action==='approve'?e.stage+' approved':e.action}} · {{who(e.actorId)}} · {{date(e.at)}}</span></div><div class="approval-actions"><v-btn v-if="canAct(a,'submit')" color="primary" size="small" :loading="busy" @click="event(a,'submit')">Submit</v-btn><v-btn v-if="canAct(a,'review')" color="primary" size="small" :loading="busy" @click="event(a,'review')">Complete review</v-btn><v-btn v-if="canAct(a,'approve')" color="primary" size="small" :loading="busy" @click="event(a,'approve')">{{approvalStageLabel(approvalStage(state,user,tenantId,a,state.events))}}</v-btn><v-btn v-if="canAct(a,'reject')" variant="outlined" color="error" size="small" :loading="busy" @click="event(a,'reject')">Reject</v-btn></div></article><v-alert v-if="failure" type="error" variant="tonal" class="mt-4">{{failure}}</v-alert></div></template></v-navigation-drawer>
<v-dialog :model-value="!!dialog" @update:model-value="v=>{if(!v)dialog=''}" :max-width="dialog==='order'?980:dialog==='import'?880:dialog==='role'?760:650" scrollable><v-card><v-card-title class="dialog-title"><span>{{({'vendor':'Vendor details','vendor-delete':'Delete project vendor','user-create':'Create user & credentials','user-credentials':'Generate new credentials','credentials':'Generated credentials','order':'New work order','amend':'Create amendment','import':'Import work order amendments','rera':'Register RERA account','tenant':'Add project','role':form.id?'Edit role':'Create role','role-delete':'Delete shared role','membership-remove':'Remove project roles','membership':'Assign project roles','form':'Financial form template','project-switch':'Select project workspace'})[dialog]}}</span><v-btn icon="mdi-close" variant="text" size="small" aria-label="Close dialog" @click="dialog=''"/></v-card-title><v-card-text><v-alert v-if="failure" type="error" variant="tonal" class="mb-5">{{failure}}</v-alert>
<template v-if="dialog==='project-switch'"><button v-for="t in tenants" :key="t.id" class="project-option" @click="tenantId=t.id;dialog='';drawer=false"><span class="project-monogram">{{t.code}}</span><span><strong>{{t.name}}</strong><small>{{t.location}}</small></span><v-icon v-if="t.id===tenantId" color="primary">mdi-check</v-icon></button><p v-if="!tenants.length">Your account has no project memberships.</p></template>
<template v-if="dialog==='order'"><v-select v-model="form.quotationId" :items="quoteOptions.map(q=>({title:q.number+' · '+q.vendor,value:q.id}))" label="Approved quotation ID *" no-data-text="Approve a selected quotation in Vendor Quotations first" @update:model-value="pickQuotation"/><v-text-field v-model="form.orderDate" type="date" label="Work order date *"/><p class="dialog-context">{{contractForForm||'Select a quotation to determine the contract type'}}</p><v-select v-model="form.vendorId" readonly :items="projectVendors.map(v=>({title:v.name,value:v.id}))" label="Project vendor *" no-data-text="Add a vendor in this project first"/><VendorProfile :profile="formVendor"/><div v-if="contractForForm==='Material construction'" class="boq-box mb-5"><v-file-input accept="application/pdf,image/png,image/jpeg" label="Signed BOQ attachment * · PDF/PNG/JPEG, up to 1 MB" @update:model-value="boqChanged"/><v-checkbox v-if="form.boq" v-model="form.boq.signed" label="I confirm this is the signed BOQ for this work order" hide-details/></div><p v-if="contractForForm==='Labour'" class="small muted mb-5">Save the labour work-order draft, raise its linked purchase order, approve the PO, then approve this work order.</p><v-text-field v-model="form.number" label="Work order number *"/><v-textarea v-model="form.description" rows="2" label="Work-order scope / summary *"/><template v-if="access('purchase_reference')==='edit'&&contractForForm!=='Labour'"><v-select v-model="form.purchaseOrderId" :items="approvedPurchases.map(p=>({title:p.number+' · '+p.vendor,value:p.id}))" label="Purchase order number (optional)" clearable no-data-text="Approve a purchase order in this project first"/><v-text-field :model-value="formPurchaseOrder?.orderDate||formPurchaseOrder?.createdAt?.slice(0,10)||''" label="Purchase order date" type="date" readonly/><p class="small muted mb-5">This links a reference. Work-order amounts and approved purchase-order costs remain separate.</p></template><div v-for="(i,index) in form.items" :key="index" class="purchase-line"><div class="approval-head mb-4"><strong>Item {{index+1}}</strong><v-btn icon="mdi-delete-outline" variant="text" color="error" :disabled="form.items.length===1" :aria-label="'Remove work-order item '+(index+1)" @click="form.items.splice(index,1)"/></div><v-textarea v-model="i.description" rows="2" label="Description of item *"/><div class="form-two-columns"><v-text-field v-model="i.unit" label="Unit *"/><v-text-field v-model="i.quantity" label="Quantity *" inputmode="decimal"/><v-text-field v-model="i.startDate" type="date" label="Period start *"/><v-text-field v-model="i.endDate" type="date" label="Period end *"/><v-text-field v-model="i.price" label="Rate per unit incl. tax (₹) *" inputmode="decimal"/><v-text-field :model-value="workEstimate(i)" label="Amount (quantity × rate)" readonly/></div><ItemFields :state="state" :user="user" :tenant-id="tenantId" form-id="work_order" :record="i"/></div><v-btn variant="outlined" prepend-icon="mdi-plus" @click="form.items.push({description:'',unit:'unit',quantity:'1',price:'',startDate:'',endDate:''})">Add item</v-btn><div class="detail-total mt-5"><span>Original work-order amount · including tax</span><strong>{{workEstimate()}}</strong><small>Sum of item amounts. Period dates do not multiply the value.</small></div><v-select v-model="form.formId" :items="versions.filter(f=>f.id==='work_order').map(f=>({title:f.name+' · v'+f.version,value:f.id}))" label="Financial template" class="mt-4"/><template v-for="f in customFields()" :key="f.key"><v-text-field v-model="form.data[f.key]" :label="f.label+(f.required?' *':'')" :type="f.type==='number'?'number':f.type==='date'?'date':'text'"/></template></template>
<template v-if="dialog==='amend'"><div class="dialog-context">{{orders.find(o=>o.id===form.orderId)?.number}} · Current {{money(effective(state,orders.find(o=>o.id===form.orderId)))}}</div><v-text-field v-model="form.amount" label="Signed amendment including tax (₹)" placeholder="200000 or -200000" hint="A positive value adds to the total. A negative value reduces it." persistent-hint/><v-textarea v-model="form.reason" rows="3" label="Reason for amendment" class="mt-5"/><v-alert type="info" variant="tonal">This creates a draft. The total changes only after manager and finance approval.</v-alert></template>
<template v-if="dialog==='import'"><p class="mb-4">Upload signed changes in INR including tax. Every row must pass validation; accepted rows become draft amendments.</p><v-btn variant="text" color="primary" prepend-icon="mdi-download-outline" @click="downloadCSV">Download CSV template</v-btn><div class="upload-box"><v-icon size="32" color="primary">mdi-cloud-upload-outline</v-icon><label for="csv-file">Choose a CSV file</label><input id="csv-file" type="file" accept=".csv,text/csv" @change="fileChanged"><span>{{csvFile||'Maximum 1 MB · up to 500 rows'}}</span></div><v-textarea v-model="csv" label="CSV content" rows="5" hint="work_order,delta_including_tax,reason" persistent-hint @update:model-value="csvPreview=null"/><v-btn color="primary" variant="outlined" :disabled="!csv" :loading="busy" class="mt-3" @click="run('preview',{csv},'',false)">Validate & preview</v-btn><template v-if="csvPreview"><v-alert :type="csvPreview.errors.length?'error':'success'" variant="tonal" class="mt-5">{{csvPreview.errors.length?'Entire upload blocked. '+csvPreview.errors.length+' validation errors.':'All rows are valid. Ready to create draft amendments.'}}</v-alert><div v-for="e in csvPreview.errors" :key="e.row" class="validation-error">Row {{e.row}}: {{e.message}}</div><div class="table-scroll mt-3"><table class="orders-table"><thead><tr><th>WORK ORDER</th><th>CHANGE</th><th>PROJECTED TOTAL</th></tr></thead><tbody><tr v-for="(r,i) in csvPreview.rows" :key="i"><td>{{r.number}}</td><td>{{r.delta>=0?'+':''}}{{money(r.delta)}}</td><td>{{money(r.next)}}</td></tr></tbody></table></div></template></template>
<template v-if="dialog==='vendor'"><v-text-field v-model="form.name" label="Vendor name *"/><v-combobox v-model="form.trade" :items="vendorTrades" label="Trade · choose or type"/><v-combobox v-model="form.vendorType" :items="vendorTypes" label="Vendor type · choose or type"/><div class="form-two-columns"><v-text-field v-model="form.contactName" label="Contact person"/><v-text-field v-model="form.phone" label="Phone"/></div><v-text-field v-model="form.email" label="Email" type="email"/><v-text-field v-model="form.gstin" label="GSTIN (optional)"/><v-text-field v-model="form.pan" label="PAN (optional)"/><v-textarea v-model="form.notes" label="Notes" rows="2"/><v-textarea v-model="form.address" label="Address" rows="2"/><MetaFields :state="state" :user="user" :tenant-id="tenantId" form-id="vendor" :record="form"/><p class="small muted">This profile belongs to {{tenant?.name}}. Editing it updates the current vendor information; issued work orders keep their original details.</p></template>
<template v-if="dialog==='vendor-delete'"><p>Remove <strong>{{form.name}}</strong> from this project's vendor directory?</p><p class="small muted mt-4">Existing work orders retain their vendor details. This vendor will no longer be available for new work orders.</p></template>
<template v-if="dialog==='user-create'"><v-text-field v-model="form.name" label="Full name *"/><v-text-field v-model="form.username" label="Username *" hint="3–64 characters: letters, numbers, dots, underscores or hyphens" persistent-hint/><v-text-field v-model="form.title" label="Designation" class="mt-4"/><p class="config-heading">Project access</p><div v-for="t in state.tenants.filter(t=>!t.deleted)" :key="t.id" class="user-project-row"><strong>{{t.name}}</strong><v-select v-model="form.projectRoles[t.id]" :items="state.roles.map(r=>({title:r.name,value:r.id}))" multiple chips label="Assigned roles" hide-details/></div><p class="small muted mt-4">No selected role means no access to that project. Form and field visibility come from the assigned roles. A password will be generated after creation.</p></template>
<template v-if="dialog==='user-credentials'"><p>Generate a new password for <strong>{{form.name}}</strong>?</p><p class="small muted mt-4">The previous password will stop working. Active sessions are signed out in the Docker version.</p></template>
<template v-if="dialog==='credentials'&&generatedCredentials"><v-alert type="success" variant="tonal" class="mb-5">Account credentials are ready. Copy them before closing; the password is shown only here.</v-alert><v-text-field :model-value="generatedCredentials.username" label="Username" readonly/><v-text-field :model-value="generatedCredentials.password" label="Generated password" readonly/><v-btn prepend-icon="mdi-content-copy" color="primary" variant="outlined" @click="copyCredentials">Copy credentials</v-btn><p v-if="demo" class="small muted mt-4">These credentials work in this sample session. Sample accounts and changes reset when the page refreshes.</p></template>
<template v-if="dialog==='rera'"><v-text-field v-model="form.number" label="Bank account number"/><v-text-field v-model="form.bank" label="Bank name"/><v-text-field v-model="form.ifsc" label="IFSC"/><v-text-field v-model="form.label" label="Account purpose / phase"/><MetaFields :state="state" :user="user" :tenant-id="tenantId" form-id="rera_account" :record="form"/><v-alert type="info" variant="tonal">The account number cannot already exist in corporate accounts or any project’s RERA accounts. Keep leading zeros; enter digits only.</v-alert></template>
<template v-if="dialog==='tenant'"><v-text-field v-model="form.name" label="Project name"/><v-text-field v-model="form.code" label="Project code" placeholder="SKY"/><v-text-field v-model="form.location" label="City, state"/></template>
<template v-if="dialog==='role-delete'"><p>Delete the shared role <strong>{{form.name}}</strong>?</p><v-alert type="warning" variant="tonal" class="mt-5">This removes {{roleAssignmentCount(form.id)}} user-project assignments across every project. Users keep their other roles; a user with no remaining roles loses access to that project. Financial and approval history is retained.</v-alert></template>
<template v-if="dialog==='membership-remove'"><p>Remove all project roles for <strong>{{form.name}}</strong> in <strong>{{tenant?.name}}</strong>?</p><v-alert type="warning" variant="tonal" class="mt-5">This user will lose access to this project. Their account, other project roles and historical records are retained.</v-alert></template>
<template v-if="dialog==='membership'"><p class="mb-5">{{who(form.userId)}} · {{tenant?.name}}</p><v-select v-model="form.roleIds" :items="state.roles.map(r=>({title:r.name,value:r.id}))" label="Project roles" multiple chips/><p class="small muted">Permissions from assigned roles are combined. With no roles, the user has no project access.</p></template>
<template v-if="dialog==='role'"><v-text-field v-model="form.name" label="Role name"/><v-select v-model="form.stage" :items="[{title:'No approval stage',value:''},{title:'Admin approver',value:'admin'},{title:'Project manager (review only)',value:'manager'},{title:'Finance approver',value:'finance'}]" label="Approval stage"/><p class="config-heading">Form permissions</p><v-select v-model="form.permissionForm" :items="versions.map(f=>({title:f.name,value:f.id}))" label="Configure form" :model-value="form.permissionForm||'work_order'" @update:model-value="id=>{form.permissionForm=id;if(!form.permissions[id])form.permissions[id]={actions:[],fields:{amount:'hidden',description:'hidden',reason:'hidden'}}}"/><div class="permission-checks"><v-checkbox v-for="a in actions" :key="a" v-model="form.permissions[form.permissionForm||'work_order'].actions" :value="a" :label="a" hide-details color="primary" density="compact"/></div><p class="config-heading mt-4">Field permissions</p><div class="field-config" v-for="key in roleFieldKeys()" :key="key"><span>{{key==='amount'?'Financial amount':key}}</span><v-select v-model="form.permissions[form.permissionForm||'work_order'].fields[key]" :items="['hidden','view','edit']" hide-details density="compact"/></div><p class="small muted mt-5">Updates affect all projects using this role. View or edit on a field does not grant access to the form itself.</p></template>
<template v-if="dialog==='form'"><v-text-field v-model="form.name" label="Form name"/><p class="small muted mb-4">{{form.id==='purchase_order'?'Number, vendor, description, material lines and totals are core fields. Configure additional fields below.':form.id==='inventory'?'Inventory is a stock ledger. Configure visibility and editing in role permissions.':form.id==='work_order'?'Work order number, vendor, scope and total are core fields. Configure additional fields below.':'Add text, numeric or date fields to this form. Required fields and role permissions apply when records are saved.'}}</p><div v-for="(f,i) in form.fields" :key="i" class="builder-row"><v-text-field v-model="f.key" label="Field key" hide-details density="compact"/><v-text-field v-model="f.label" label="Label" hide-details density="compact"/><v-select v-model="f.type" :items="['text','number','date']" label="Type" hide-details density="compact"/><v-checkbox v-model="f.required" label="Required" hide-details density="compact"/><v-btn icon="mdi-close" size="small" variant="text" :aria-label="'Remove field '+(i+1)" @click="form.fields.splice(i,1)"/></div><v-btn variant="outlined" prepend-icon="mdi-plus" @click="form.fields.push({key:'field_'+(form.fields.length+1),label:'',type:'text',required:false})">Add field</v-btn><template v-if="['work_order','purchase_order'].includes(form.id)"><p class="config-heading mt-5">Fields on individual items</p><div v-for="(f,i) in form.itemFields" :key="i" class="builder-row"><v-text-field v-model="f.key" label="Item field key"/><v-text-field v-model="f.label" label="Label"/><v-select v-model="f.type" :items="['text','number','date']" label="Type"/><v-checkbox v-model="f.required" label="Required on every item"/><v-btn icon="mdi-close" variant="text" @click="form.itemFields.splice(i,1)"/></div><v-btn variant="outlined" @click="form.itemFields.push({key:'detail_'+(form.itemFields.length+1),label:'',type:'text',required:false})">Add item field</v-btn><p class="small muted mt-3">Optional fields can be filled on Item 1 or any other item. Set item field permissions in Users &amp; roles.</p></template><v-alert type="info" variant="tonal" class="mt-5">Publishing creates a new version. Existing financial records keep their original template version.</v-alert></template>
</v-card-text><v-card-actions v-if="dialog!=='project-switch'" class="dialog-actions"><v-btn variant="text" @click="dialog=''">Cancel</v-btn><v-spacer/><v-btn v-if="dialog==='role-delete'" color="error" variant="flat" :loading="busy" @click="run('role-delete',{id:form.id},'Shared role deleted and assignments removed')">Delete role</v-btn><v-btn v-if="dialog==='membership-remove'" color="error" variant="flat" :loading="busy" @click="run('membership',{userId:form.userId,roleIds:[]},'Project roles removed')">Remove project roles</v-btn><v-btn v-if="dialog==='vendor'" color="primary" variant="flat" :loading="busy" @click="run('vendor',form,'Vendor saved')">Save vendor</v-btn><v-btn v-if="dialog==='vendor-delete'" color="error" variant="flat" :loading="busy" @click="run('vendor-delete',form,'Vendor removed from directory')">Delete vendor</v-btn><v-btn v-if="dialog==='user-create'" color="primary" variant="flat" :loading="busy" @click="run('user-create',form,'User created')">Create & generate credentials</v-btn><v-btn v-if="dialog==='user-credentials'" color="primary" variant="flat" :loading="busy" @click="run('user-credentials',form,'Credentials generated')">Generate credentials</v-btn><v-btn v-if="dialog==='credentials'" color="primary" variant="flat" @click="dialog=''">Done</v-btn><v-btn color="primary" variant="flat" :loading="busy" v-if="dialog==='order'" @click="saveOrder">Create work order</v-btn><v-btn color="primary" variant="flat" :loading="busy" v-if="dialog==='amend'" @click="saveAmend">Save draft amendment</v-btn><v-btn color="primary" variant="flat" :loading="busy" v-if="dialog==='import'" :disabled="!csvPreview||csvPreview.errors.length>0" @click="run('import',{csv,filename:csvFile||'pasted-amendments.csv'},'CSV imported as draft amendments')">Import all rows</v-btn><v-btn v-if="['rera','tenant','role','membership','form'].includes(dialog)" color="primary" variant="flat" :loading="busy" @click="run(dialog,form,dialog==='form'?'New form version published':'Configuration saved')">{{dialog==='form'?'Publish new version':dialog==='role'?'Save role':dialog==='membership'?'Save project roles':'Save'}}</v-btn></v-card-actions></v-card></v-dialog>
<v-snackbar :model-value="!!toast" @update:model-value="v=>{if(!v)toast=''}" color="secondary" timeout="3500">{{toast}}</v-snackbar>
</v-app>
</template>
